-amber-700 dark:text-amber-300"><?= html_escape(isset($labels['finance_pending_approver_unassigned'])?$labels['finance_pending_approver_unassigned']:'Waiting for approver assignment') ?></div>';}if(v==='revise'&&row.revise_note){html+='<div class="max-w-xs border-l-2 border-amber-300 pl-2 text-xs leading-5 text-amber-800 dark:text-amber-300" title="'+escapeHtml(row.revise_note)+'"><span class="font-medium"><?= html_escape(isset($labels['finance_tx_revise_reason'])?$labels['finance_tx_revise_reason']:'Revision reason') ?>:</span> '+escapeHtml(row.revise_note)+'</div>';}return html+'</div>';}}
